name: PR Commit Security Scan

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  security-scan:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '18'
          cache: 'npm'

      - name: Install dependencies
        run: npm ci

      - name: Run Brin Security Scan
        id: brin-scan
        uses: brin-security/brin-action@v1
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          api_key: ${{ secrets.BRIN_API_KEY }}
          fail_on_dangerous: true
          min_score: 30

      - name: Update PR Comment with Results
        if: always()
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const comment = comments.find(c => c.body.includes('Brin Security Scan Results'));

            let summary = `### Brin Security Scan Results\n\n`;
            summary += `**Status:** ${process.env.BRIN_SCAN_STATUS || 'Unknown'}\n\n`;

            if (process.env.BRIN_BLOCKING_FINDINGS) {
              summary += `**Blocking Findings:** ${process.env.BRIN_BLOCKING_FINDINGS}\n\n`;
            }

            if (process.env.BRIN_REVIEW_FINDINGS) {
              summary += `**Review Findings:** ${process.env.BRIN_REVIEW_FINDINGS}\n\n`;
            }

            if (process.env.BRIN_INCONCLUSIVE_FINDINGS) {
              summary += `**Inconclusive Findings:** ${process.env.BRIN_INCONCLUSIVE_FINDINGS}\n\n`;
            }

            if (comment) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: comment.id,
                body: summary
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: summary
              });
            }

      - name: Remove Comment if Clean
        if: success() && steps.brin-scan.outputs.dangerous === 'false'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const comment = comments.find(c => c.body.includes('Brin Security Scan Results'));

            if (comment) {
              await github.rest.issues.deleteComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: comment.id
              });
            }
